const IndustrialHero = lazy(() => import("@/components/IndustrialHero").then(module => ({ default: module.IndustrialHero })));

function useGwaveCopy() {
  const { language } = useLanguage();
  const copy = (en: string, my: string) => language === "my" ? my : en;
  return { language, copy };
}

function SectionKicker({ children }: { children: React.ReactNode }) {
  return <p className="font-mono text-[10px] uppercase tracking-[0.25em] text-[#8bd32c]">{children}</p>;
}

function EmptyState({ title, children }: { title: string; children: React.ReactNode }) {
  return <div className="border border-dashed border-white/25 bg-white/[0.02] p-6"><p className="font-display text-3xl font-bold uppercase tracking-tight">{title}</p><p className="mt-3 max-w-lg text-sm leading-6 text-white/55">{children}</p></div>;
}

function LiveHighlights() {
  const { copy } = useGwaveCopy();
  const featured = trpc.gwave.catalogue.list.useQuery({ category: "merch", featured: true });
  const latest = trpc.gwave.news.published.useQuery();
  const products = featured.data ?? [];
  const posts = latest.data?.slice(0, 3) ?? [];
  return <section className="border-y border-white/15 bg-[#0a0a0a]"><div className="mx-auto grid max-w-[1600px] gap-px bg-white/20 lg:grid-cols-2"><div className="bg-[#0a0a0a] p-6 md:p-8"><SectionKicker>{copy("Live / Featured products", "Live / Featured products")}</SectionKicker><h2 className="mt-3 font-display text-5xl font-black uppercase tracking-[-.07em]">{copy("Current", "လက်ရှိ")}<br/>{copy("objects.", "ပစ္စည်းများ။")}</h2><div className="mt-8 grid gap-3">{products.length ? products.map(product => <Link key={product.id} href={`/products/${product.id}`} className="industrial-hover group flex items-center justify-between border-t border-white/15 py-4"><span><span className="block font-display text-3xl font-bold uppercase group-hover:text-[#8bd32c]">{product.name}</span><span className="font-mono text-[10px] uppercase tracking-[.15em] text-white/45">{product.category}</span></span><span className="font-mono text-xs">{(product.basePriceCents / 100).toLocaleString(undefined, { style: "currency", currency: "USD" })}</span></Link>) : <p className="text-sm leading-6 text-white/50">No featured merchandise has been published. Approved product records will appear here automatically.</p>}</div><Link href="/store" className="mt-7 inline-block font-mono text-[10px] uppercase tracking-[.18em] text-[#8bd32c]">{copy("Open product catalogue", "Product catalogue ဖွင့်ရန်")} →</Link></div><div className="bg-[#0a0a0a] p-6 md:p-8"><SectionKicker>{copy("Live / Latest news", "Live / နောက်ဆုံးသတင်း")}</SectionKicker><h2 className="mt-3 font-display text-5xl font-black uppercase tracking-[-.07em]">{copy("Current", "လက်ရှိ")}<br/>{copy("signal.", "signal။")}</h2><div className="mt-8 grid gap-3">{posts.length ? posts.map(post => <Link key={post.id} href="/news" className="industrial-hover group border-t border-white/15 py-4"><span className="font-mono text-[10px] uppercase tracking-[.15em] text-[#8bd32c]">{post.category.replaceAll("_", " ")}</span><span className="mt-2 block font-display text-3xl font-bold uppercase group-hover:text-[#8bd32c]">{post.title}</span></Link>) : <p className="text-sm leading-6 text-white/50">No approved posts are live. The editorial queue will surface content here only after the final publication state.</p>}</div><Link href="/news" className="mt-7 inline-block font-mono text-[10px] uppercase tracking-[.18em] text-[#8bd32c]">{copy("Open newsfeed", "Newsfeed ဖွင့်ရန်")} →</Link></div></div></section>;
}

