  const merch = trpc.gwave.catalogue.list.useQuery(merchInput);
  const ageStatus = trpc.gwave.age.status.useQuery(undefined, { enabled: isAuthenticated });
  const restrictedInput = useMemo(() => ({ restricted: true }), []);
  const restricted = trpc.gwave.catalogue.list.useQuery(restrictedInput, { enabled: Boolean(isAuthenticated && ageStatus.data?.confirmed) });
  const merchItems = merch.data ?? [];
